const { createChannelNotifier } = require('./createChannelNotifier');

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function footerFor(config, user, message) {
  if (message.category === 'transactional' || message.category === 'security') {
    return `Sent to ${user.email} because of recent account activity.`;
  }
  const url = `${config.unsubscribeBaseUrl}?user=${encodeURIComponent(user.id)}`;
  return `You can unsubscribe at ${url}.`;
}

const emailStrategy = {
  channel: 'email',
  defaultMaxPerHour: 8,
  transportName: 'email',
  transportError: 'email transport is not configured',

  settings: options => ({
    from: options.from || 'noreply@example.com',
    replyTo: options.replyTo || 'support@example.com',
    unsubscribeBaseUrl: options.unsubscribeBaseUrl || 'https://example.com/unsubscribe'
  }),

  validateUser(user) {
    if (!user.email || !user.email.includes('@')) {
      throw new TypeError('user.email is required for email notifications');
    }
  },

  shouldThrottle({ user, message }, baseCheck) {
    const base = baseCheck();
    if (base.throttled) {
      return base;
    }
    if (message.category === 'marketing' && !user.emailOptIn) {
      return { throttled: true, reason: 'user has not opted into marketing email', retryAt: null };
    }
    return { throttled: false };
  },

  format({ user, message, config }, base) {
    const subjectPrefix = message.category === 'security' ? '[Action Required] ' : '';
    const footer = footerFor(config, user, message);

    return {
      ...base,
      to: user.email,
      from: config.from,
      replyTo: config.replyTo,
      subject: `${subjectPrefix}${base.title}`,
      text: `${base.body}\n\n${footer}`,
      html: `<h1>${escapeHtml(base.title)}</h1><p>${escapeHtml(base.body)}</p><footer>${escapeHtml(footer)}</footer>`,
      preview: base.body.slice(0, 90)
    };
  }
};

